CREATE TABLE IF NOT EXISTS gratitude_letters (
    id BIGSERIAL PRIMARY KEY,
    email VARCHAR(150),
    employee_code VARCHAR(50) NOT NULL,
    full_name VARCHAR(150) NOT NULL,
    salutation VARCHAR(20) DEFAULT 'Anh/Chị',
    unit_name VARCHAR(150),
    days_of_service INT NOT NULL,
    years_desc VARCHAR(255),
    is_opened BOOLEAN DEFAULT FALSE,
    opened_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_gratitude_email ON gratitude_letters(email);
CREATE INDEX IF NOT EXISTS idx_gratitude_code ON gratitude_letters(employee_code);


--rollback DROP TABLE IF EXISTS gratitude_letters;